package synth

import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

class Counter110 {
    var current: Int by Delegates.observable(51) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
data class Pair111<A, B>(val first: A, val second: B)

fun combine111(left: Int, right: Int): Pair111<Int, Int> {
    return Pair111(left + 58, right + 36)
}
sealed class Outcome112 {
    data class Success(val payload: String) : Outcome112()
    data object Failure : Outcome112()
}

fun describe112(outcome: Outcome112): String = when (outcome) {
    is Outcome112.Success -> outcome.payload
    Outcome112.Failure -> "failed"
}
